export interface Ros2Tools {
  /**
   * Call a ROS 2 service and return its response. request: the request's fields as a dict
   * (its type is found from the graph), or omitted for an empty request. Time passes while it waits.
   */
  call(args: {
    service: string;
    request?: Record<string, unknown> | null;
    timeout?: number | null;
  }): Promise<string>;
  /**
   * What is running behind ROS 2 before connecting to it: the robot's description, its
   * joints, its controllers and how each is driven, whether it runs on simulation time,
   * whether Gazebo is there, and the ros2 settings to give robot_launch(backend="ros2").
   */
  inspect(args?: {
    namespace?: string | null;
    timeout?: number | null;
  }): Promise<string>;
  /**
   * What the ROS 2 graph has now: kind is topics (with publisher and subscriber counts), services or actions;
   * filter keeps names containing it. Then read one with ros2_topic, call with ros2_call, or ros2_send_goal.
   */
  list(args?: {
    kind?: string | null;
    filter?: string | null;
  }): Promise<string>;
  /**
   * The ROS 2 nodes' log lines (/rosout, the console) since the world started: level DEBUG, INFO, WARN, ERROR
   * or FATAL and above; node: part of a node's name; the newest lines of them, at their simulated time.
   */
  logs(args?: {
    level?: string | null;
    node?: string | null;
    lines?: number | null;
  }): Promise<string>;
  /**
   * Publish one message on a ROS 2 topic: its fields as a dict; the type comes from the
   * graph, or pass type="pkg/msg/Name" for a topic nobody has published yet.
   */
  publish(args: {
    topic: string;
    message: Record<string, unknown>;
    type?: string | null;
  }): Promise<string>;
  /**
   * Send a goal to a ROS 2 action server and wait for its result: succeeded, aborted,
   * canceled or rejected, and the result. goal: its fields as a dict. A goal on the arm's own
   * controller takes the arm from robowright until robowright next moves it.
   */
  sendGoal(args: {
    action: string;
    goal?: Record<string, unknown> | null;
    timeout?: number | null;
  }): Promise<string>;
  /**
   * The newest message on a ROS 2 topic, with its rate and how many have arrived. Works on a
   * robot behind ROS 2 (robot_launch backend="ros2") or a world served with robot_serve_ros2.
   */
  topic(args: {
    name: string;
    timeout?: number | null;
  }): Promise<string>;
  /**
   * What has gone over the ROS 2 graph since the world started (the network log): each topic's type, who
   * publishes and subscribes, how many messages at what rate and when; and topics subscribed to that nobody
   * publishes, which is where a stack waiting for something says so.
   */
  traffic(args?: {
    limit?: number | null;
  }): Promise<string>;
}

export interface SimTools {
  /**
   * Attach to a simulation someone else built, and watch and drive it. env_id: a registered gymnasium id
   * (e.g. "FetchPickAndPlace-v4", "gym_aloha/AlohaTransferCube-v0"; kwargs as gymnasium.make takes them), or
   * gymnasium's own "module:EnvId" form, which imports the module first. If the id is not registered yet,
   * the installed environment packages (gymnasium-robotics, ManiSkill, panda-gym, gym-aloha, ...) are
   * imported to register theirs, then it is retried. entry_point: "module:callable" that returns an
   * environment, called with kwargs (Meta-World: entry_point="metaworld:make_mt_envs",
   * kwargs={"name": "pick-place-v3", "seed": 0}). It is reset with seed (None: not seeded). Closes any open
   * world. Time moves only when sim_env_step steps the environment: their own loop is not robowright's.
   * Returns the snapshot, or why it could not attach: the ids that look like env_id, which packages were
   * registered, and which imports failed.
   */
  attach(args?: {
    env_id?: string | null;
    kwargs?: Record<string, unknown> | null;
    seed?: number | null;
    entry_point?: string | null;
  }): Promise<string>;
  /**
   * Step the attached environment's own step this many times. action: its action, with the shape of its
   * action space; None is the zero (no-op) action, or with sample=true a random one from the action space.
   * Returns the reward summed over the steps, whether the episode ended, which named bodies moved, and the
   * snapshot. Every step is recorded (robot_save_trace keeps it).
   */
  envStep(args?: {
    action?: Array<number> | null;
    steps?: number | null;
    sample?: boolean | null;
  }): Promise<string>;
  /**
   * Pause the simulator (Gazebo). Its clock stops: so do the ROS 2 stack's timers on sim time.
   */
  pause(): Promise<string>;
  /**
   * Let the paused simulator (Gazebo) run again.
   */
  play(): Promise<string>;
  /**
   * Remove a model from the simulator (Gazebo).
   */
  remove(args: {
    name: string;
  }): Promise<string>;
  /**
   * Add an object to the simulator (Gazebo): {"name", "kind": box|cylinder|sphere|bin,
   * "size", "pos", "color", "mass"}, as robot_launch's objects.
   */
  spawn(args: {
    object: Record<string, unknown>;
  }): Promise<string>;
  /**
   * The simulator's own state (Gazebo): its clock, iterations, paused or running, real-time
   * factor, and every model in it. Also the world's own time, which snapshots report as t and
   * which counts from launch; Gazebo's clock need not match it.
   */
  state(): Promise<string>;
  /**
   * Advance the simulator (Gazebo) exactly this many physics iterations, paused before and
   * after: to look at a moment closely.
   */
  step(args?: {
    iterations?: number | null;
  }): Promise<string>;
  /**
   * The names an attached simulation takes: bodies (free bodies are objects, starred), sites, joints and
   * cameras. Bodies and sites go to robot_expect, robot_push, robot_move_object; a joint to robot_expect with
   * matcher to_be_between {lo, hi}; a camera to robot_screenshot.
   */
  subjects(): Promise<string>;
}

export interface Assertions {
  toBeAbove(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeAtRest(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeClosed(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeHidden(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeHolding(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeInside(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeNear(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeOpen(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeTouching(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeUpright(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toBeVisible(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toHaveJoint(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  toHaveNoCollisions(arg?: unknown, options?: Record<string, unknown> & { timeout?: number }): Promise<string>;
  /** The same matchers, expecting the opposite. */
  readonly not: Assertions;
}

export interface LaunchOptions {
  /** The command that starts the server; default ["robowright", "mcp"] (or ROBOWRIGHT_COMMAND, split on spaces). */
  command?: string[];
  /** Environment for the server process (default: this process's). */
  env?: Record<string, string | undefined>;
  /** Working directory for the server process. */
  cwd?: string;
  /** Where the server's stderr goes: "inherit" (default) or "ignore". */
  stderr?: "inherit" | "ignore";
}

export class RobowrightError extends Error {
  /** The tool that failed, e.g. "robot_pick". */
  readonly tool: string;
}

/** An expectation that did not hold (robot_expect returned FAIL). */
export class ExpectationError extends Error {
  readonly tool: string;
}

export class Robowright {
  readonly robot: RobotTools;
  readonly ros2: Ros2Tools;
  readonly sim: SimTools;
  /** Playwright-style assertions; a failing one throws ExpectationError. */
  expect(subject: string, options?: { timeout?: number }): Assertions;
  /** Call any tool by its MCP name, e.g. call("robot_pick", { object: "cube" }). */
  call(tool: string, args?: Record<string, unknown>): Promise<string>;
  /** Stop the server (closing its worlds). */
  close(): Promise<void>;
  /** The server's name and version. */
  readonly server: { name: string; version: string };
}

/** Start the robowright MCP server and connect to it. */
export function launch(options?: LaunchOptions): Promise<Robowright>;
